const crypto = require('crypto');
const body = $input.item.json.body;
const secret = $vars.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET variable is not configured');
if (!body.deliveryId || !body.nonce || !body.payloadBase64 || !body.signature) throw new Error('deliveryId, nonce, payloadBase64, and signature are required');
if (Math.abs(Math.floor(Date.now() / 1000) - body.timestamp) > 300) throw new Error('Webhook timestamp expired');
const expected = crypto.createHmac('sha256', secret).update(`${body.timestamp}.${body.nonce}.${body.payloadBase64}`).digest('hex');
const expectedBuffer = Buffer.from(expected, 'hex');
const receivedBuffer = Buffer.from(body.signature, 'hex');
if (expectedBuffer.length !== receivedBuffer.length || !crypto.timingSafeEqual(expectedBuffer, receivedBuffer)) throw new Error('Webhook signature invalid');
const replay = $getWorkflowStaticData('global');
replay.deliveries ??= {};
replay.nonces ??= {};
const cutoff = Date.now() - 15 * 60 * 1000;
for (const [key, value] of Object.entries(replay.deliveries)) if (value < cutoff) delete replay.deliveries[key];
for (const [key, value] of Object.entries(replay.nonces)) if (value < cutoff) delete replay.nonces[key];
if (replay.deliveries[body.deliveryId] || replay.nonces[body.nonce]) return [];
replay.deliveries[body.deliveryId] = Date.now();
replay.nonces[body.nonce] = Date.now();
const payload = JSON.parse(Buffer.from(body.payloadBase64, 'base64url').toString('utf8'));
if (!payload.incidentId) throw new Error('incidentId is required');
return [{ json: { ...body, payload } }];

const source = $('Verify HMAC and Replay Window').item.json;
if ($json.duplicate === true) return [];
return [{ json: source }];

