const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET variable is not configured');
const source = $('Verify HMAC and Replay Window').item.json;
const payloadBase64 = Buffer.from(JSON.stringify({ incidentId: source.payload.incidentId, status: 'delivered' })).toString('base64url');
const timestamp = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${payloadBase64}`).digest('hex');
return [{ json: { deliveryId: source.deliveryId, timestamp, nonce, payloadBase64, signature, payload: { incidentId: source.payload.incidentId, status: 'delivered' } } }];
